  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Body,
  6→  Query,
  7→  UseGuards,
  8→  Request,
  9→  NotFoundException,
 10→} from '@nestjs/common';
 11→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
 12→import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
 13→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
 14→import { IpnsService } from './ipns.service';
 15→import {
 16→  PublishIpnsDto,
 17→  PublishIpnsResponseDto,
 18→  BatchPublishIpnsDto,
 19→  BatchPublishIpnsResponseDto,
 20→  ResolveIpnsQueryDto,
 21→  ResolveIpnsResponseDto,
 22→} from './dto';
 23→import { MetricsService } from '../metrics/metrics.service';
 24→import { RequestWithUser } from '../common/types';
 25→
 26→@ApiTags('IPNS')
 27→@ApiBearerAuth()
 28→@UseGuards(JwtAuthGuard, ThrottlerGuard)
 29→@Controller('ipns')
 30→export class IpnsController {
 31→  constructor(
 32→    private readonly ipnsService: IpnsService,
 33→    private readonly metricsService: MetricsService
 34→  ) {}
 35→
 36→  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
 37→  // Each publish makes external HTTP calls to delegated-ipfs.dev
 38→  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
 39→  @Post('publish')
 40→  @ApiOperation({
 41→    summary: 'Publish IPNS record',
 42→    description:
 43→      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
 44→      'The client signs the record locally; backend relays to delegated-ipfs.dev and tracks ' +
 45→      'the folder for TEE republishing.',
 46→  })
 47→  @ApiResponse({
 48→    status: 200,
 49→    description: 'IPNS record published successfully',
 50→    type: PublishIpnsResponseDto,
 51→  })
 52→  @ApiResponse({
 53→    status: 400,
 54→    description: 'Bad Request - Invalid record format or missing required fields',
 55→  })
 56→  @ApiResponse({
 57→    status: 401,
 58→    description: 'Unauthorized - JWT token required',
 59→  })
 60→  @ApiResponse({
 61→    status: 502,
 62→    description: 'Bad Gateway - Failed to publish to delegated routing',
 63→  })
 64→  async publishRecord(
 65→    @Request() req: RequestWithUser,
 66→    @Body() dto: PublishIpnsDto
 67→  ): Promise<PublishIpnsResponseDto> {
 68→    const result = await this.ipnsService.publishRecord(req.user.id, dto);
 69→    this.metricsService.ipnsPublishes.inc({ type: 'single' });
 70→    return result;
 71→  }
 72→
 73→  // [SECURITY: HIGH-04] Rate limit batch publish - lower limit since each batch can have up to 200 records
 74→  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch publishes per minute per user
 75→  @Post('publish-batch')
 76→  @ApiOperation({
 77→    summary: 'Batch publish IPNS records',
 78→    description:
 79→      'Publish multiple IPNS records (folder and/or file) in a single API call. ' +
 80→      'Supports up to 200 records per batch with concurrency-limited processing. ' +
 81→      'Partial success is allowed: individual record failures do not fail the batch.',
 82→  })
 83→  @ApiResponse({
 84→    status: 200,
 85→    description: 'Batch publish results with per-record outcomes',
 86→    type: BatchPublishIpnsResponseDto,
 87→  })
 88→  @ApiResponse({
 89→    status: 400,
 90→    description: 'Bad Request - Invalid record format or batch exceeds 200 entries',
 91→  })
 92→  @ApiResponse({
 93→    status: 401,
 94→    description: 'Unauthorized - JWT token required',
 95→  })
 96→  @ApiResponse({
 97→    status: 502,
 98→    description: 'Bad Gateway - Delegated routing failures (partial results may be returned)',
 99→  })
100→  async publishBatch(
101→    @Request() req: RequestWithUser,
102→    @Body() dto: BatchPublishIpnsDto
103→  ): Promise<BatchPublishIpnsResponseDto> {
104→    const result = await this.ipnsService.publishBatch(req.user.id, dto);
105→    this.metricsService.ipnsPublishes.inc({ type: 'batch' }, result.totalSucceeded);
106→    return result;
107→  }
108→
109→  // [SECURITY: HIGH-04] Rate limit IPNS resolve - higher limit than publish since read-only
110→  @Throttle({ default: { limit: 30, ttl: 60000 } }) // 30 resolves per minute per user
111→  @Get('resolve')
112→  @ApiOperation({
113→    summary: 'Resolve IPNS name',
114→    description:
115→      'Resolve an IPNS name to its current CID via delegated routing. ' +
116→      'Returns the CID and sequence number of the current IPNS record.',
117→  })
118→  @ApiQuery({
119→    name: 'ipnsName',
120→    description:
121→      'IPNS name to resolve. Supports CIDv1 IPNS names starting with "k51..." (PeerID-style) or "bafzaa..." (IPNS key CID).',
122→    example: 'REDACTED',
123→  })
124→  @ApiResponse({
125→    status: 200,
126→    description: 'IPNS name resolved successfully',
127→    type: ResolveIpnsResponseDto,
128→  })
129→  @ApiResponse({
130→    status: 400,
131→    description: 'Bad Request - Invalid IPNS name format',
132→  })
133→  @ApiResponse({
134→    status: 401,
135→    description: 'Unauthorized - JWT token required',
136→  })
137→  @ApiResponse({
138→    status: 404,
139→    description: 'Not Found - IPNS name not published or not found in routing network',
140→  })
141→  @ApiResponse({
142→    status: 502,
143→    description: 'Bad Gateway - Failed to resolve from delegated routing',
144→  })
145→  async resolveRecord(@Query() query: ResolveIpnsQueryDto): Promise<ResolveIpnsResponseDto> {
146→    const result = await this.ipnsService.resolveRecord(query.ipnsName);
147→
148→    if (!result) {
149→      throw new NotFoundException('IPNS name not found in routing network');
150→    }
151→
152→    // Track resolve source: if signatureV2 is present, it came from the network
153→    const source = result.signatureV2 ? 'network' : 'db_cache';
154→    this.metricsService.ipnsResolves.inc({ source });
155→
156→    // Include signature fields as all-or-nothing bundle for client verification
157→    const hasSigData = result.signatureV2 && result.data && result.pubKey;
158→    return {
159→      success: true,
160→      cid: result.cid,
161→      sequenceNumber: result.sequenceNumber,
162→      ...(hasSigData && {
163→        signatureV2: result.signatureV2,
164→        data: result.data,
165→        pubKey: result.pubKey,
166→      }),
167→    };
168→  }
169→}
