  1→import {
  2→  Injectable,
  3→  HttpException,
  4→  HttpStatus,
  5→  BadRequestException,
  6→  Logger,
  7→  Inject,
  8→  forwardRef,
  9→} from '@nestjs/common';
 10→import { InjectRepository } from '@nestjs/typeorm';
 11→import { Repository } from 'typeorm';
 12→import { FolderIpns } from './entities/folder-ipns.entity';
 13→import {
 14→  PublishIpnsDto,
 15→  PublishIpnsResponseDto,
 16→  BatchPublishIpnsDto,
 17→  BatchPublishIpnsResponseDto,
 18→} from './dto';
 19→import { RepublishService } from '../republish/republish.service';
 20→import { DelegatedRoutingClient } from './delegated-routing.client';
 21→import { parseIpnsRecord } from './ipns-record-parser';
 22→
 23→@Injectable()
 24→export class IpnsService {
 25→  private readonly logger = new Logger(IpnsService.name);
 26→
 27→  constructor(
 28→    @InjectRepository(FolderIpns)
 29→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 30→    private readonly delegatedRouting: DelegatedRoutingClient,
 31→    @Inject(forwardRef(() => RepublishService))
 32→    private readonly republishService: RepublishService
 33→  ) {}
 34→
 35→  /**
 36→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 37→   * and track the folder in the database for TEE republishing
 38→   */
 39→  async publishRecord(userId: string, dto: PublishIpnsDto): Promise<PublishIpnsResponseDto> {
 40→    // Validate base64 record
 41→    let recordBytes: Uint8Array;
 42→    try {
 43→      recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 44→    } catch {
 45→      throw new BadRequestException('Invalid base64-encoded record');
 46→    }
 47→
 48→    // Save to DB first so resolve always has a fallback, even if delegated
 49→    // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 50→    const folder = await this.upsertFolderIpns(
 51→      userId,
 52→      dto.ipnsName,
 53→      dto.metadataCid,
 54→      dto.encryptedIpnsPrivateKey,
 55→      dto.keyEpoch
 56→    );
 57→
 58→    // Publish to delegated routing API (best-effort — DB is the reliable source)
 59→    try {
 60→      await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
 61→    } catch (error) {
 62→      this.logger.warn(
 63→        `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 64→      );
 65→    }
 66→
 67→    return {
 68→      success: true,
 69→      ipnsName: dto.ipnsName,
 70→      sequenceNumber: folder.sequenceNumber,
 71→    };
 72→  }
 73→
 74→  /**
 75→   * Batch publish multiple IPNS records with concurrency-limited processing.
 76→   * Supports partial success: individual record failures do not fail the batch.
 77→   * Processes up to 10 records concurrently.
 78→   */
 79→  async publishBatch(
 80→    userId: string,
 81→    dto: BatchPublishIpnsDto
 82→  ): Promise<BatchPublishIpnsResponseDto> {
 83→    const results: PublishIpnsResponseDto[] = [];
 84→    let totalSucceeded = 0;
 85→    let totalFailed = 0;
 86→
 87→    const CONCURRENCY = 10;
 88→
 89→    // Process records in batches of CONCURRENCY
 90→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
 91→      const batch = dto.records.slice(i, i + CONCURRENCY);
 92→
 93→      const settled = await Promise.allSettled(
 94→        batch.map(async (entry) => {
 95→          // Validate base64 record
 96→          let recordBytes: Uint8Array;
 97→          try {
 98→            recordBytes = Uint8Array.from(atob(entry.record), (c) => c.charCodeAt(0));
 99→          } catch {
100→            throw new BadRequestException(`Invalid base64-encoded record for ${entry.ipnsName}`);
101→          }
102→
103→          // Save to DB first so resolve always has a fallback
104→          const folder = await this.upsertFolderIpns(
105→            userId,
106→            entry.ipnsName,
107→            entry.metadataCid,
108→            entry.encryptedIpnsPrivateKey,
109→            entry.keyEpoch,
110→            entry.recordType ?? 'folder'
111→          );
112→
113→          // Publish to delegated routing (best-effort)
114→          try {
115→            await this.delegatedRouting.publish(entry.ipnsName, recordBytes);
116→          } catch (error) {
117→            this.logger.warn(
118→              `Delegated routing publish failed for ${entry.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
119→            );
120→          }
121→
122→          return {
123→            success: true,
124→            ipnsName: entry.ipnsName,
125→            sequenceNumber: folder.sequenceNumber,
126→          } as PublishIpnsResponseDto;
127→        })
128→      );
129→
130→      for (let j = 0; j < settled.length; j++) {
131→        const result = settled[j];
132→        if (result.status === 'fulfilled') {
133→          results.push(result.value);
134→          totalSucceeded++;
135→        } else {
136→          const reason = result.reason;
137→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
138→          this.logger.warn(
139→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
140→          );
141→          results.push({
142→            success: false,
143→            ipnsName,
144→            sequenceNumber: '0',
145→          });
146→          totalFailed++;
147→        }
148→      }
149→    }
150→
151→    return { results, totalSucceeded, totalFailed };
152→  }
153→
154→  /**
155→   * Create or update a folder/file IPNS entry.
156→   * Handles both folder metadata and per-file metadata IPNS records.
157→   */
158→  private async upsertFolderIpns(
159→    userId: string,
160→    ipnsName: string,
161→    metadataCid: string,
162→    encryptedIpnsPrivateKey?: string,
163→    keyEpoch?: number,
164→    recordType: 'folder' | 'file' = 'folder'
165→  ): Promise<FolderIpns> {
166→    const existing = await this.getFolderIpns(userId, ipnsName);
167→
168→    if (existing) {
169→      // Update existing entry
170→      existing.latestCid = metadataCid;
171→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
172→      existing.recordType = recordType;
173→      existing.updatedAt = new Date();
174→
175→      // Only update encrypted key if provided (e.g., on key rotation)
176→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
177→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
178→        existing.keyEpoch = keyEpoch;
179→      }
180→
181→      const saved = await this.folderIpnsRepository.save(existing);
182→
183→      // Auto-enroll for TEE republishing when encrypted key is provided
184→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
185→        this.republishService
186→          .enrollFolder(
187→            userId,
188→            ipnsName,
189→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
190→            keyEpoch,
191→            metadataCid,
192→            saved.sequenceNumber
193→          )
194→          .catch((err) =>
195→            this.logger.warn(
196→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
197→            )
198→          );
199→      }
200→
201→      return saved;
202→    }
203→
204→    // Create new entry
205→    const folder = this.folderIpnsRepository.create({
206→      userId,
207→      ipnsName,
208→      latestCid: metadataCid,
209→      sequenceNumber: '0',
210→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
211→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
212→        : null,
213→      keyEpoch: keyEpoch ?? null,
214→      isRoot: false, // Root folder is tracked in Vault entity
215→      recordType,
216→    });
217→
218→    const saved = await this.folderIpnsRepository.save(folder);
219→
220→    // Auto-enroll for TEE republishing when encrypted key is provided
221→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
222→      this.republishService
223→        .enrollFolder(
224→          userId,
225→          ipnsName,
226→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
227→          keyEpoch,
228→          metadataCid,
229→          saved.sequenceNumber
230→        )
231→        .catch((err) =>
232→          this.logger.warn(
233→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
234→          )
235→        );
236→    }
237→
238→    return saved;
239→  }
240→
241→  /**
242→   * Get a folder IPNS entry by user and IPNS name
243→   */
244→  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
245→    return this.folderIpnsRepository.findOne({
246→      where: { userId, ipnsName },
247→    });
248→  }
249→
250→  /**
251→   * Get all folder IPNS entries for a user (for TEE republishing)
252→   */
253→  async getAllFolderIpns(userId: string): Promise<FolderIpns[]> {
254→    return this.folderIpnsRepository.find({
255→      where: { userId },
256→      order: { createdAt: 'ASC' },
257→    });
258→  }
259→
260→  /**
261→   * Resolve an IPNS name to its current CID via delegated routing,
262→   * falling back to the DB-cached CID when delegated routing is unavailable
263→   * or when the record is not found in the DHT.
264→   * Returns null if the IPNS name is not found anywhere (404)
265→   */
266→  async resolveRecord(ipnsName: string): Promise<{
267→    cid: string;
268→    sequenceNumber: string;
269→    signatureV2?: string;
270→    data?: string;
271→    pubKey?: string;
272→  } | null> {
273→    let result: {
274→      cid: string;
275→      sequenceNumber: string;
276→      signatureV2?: string;
277→      data?: string;
278→      pubKey?: string;
279→    } | null = null;
280→
281→    try {
282→      const recordBytes = await this.delegatedRouting.resolve(ipnsName);
283→      if (recordBytes) {
284→        result = this.parseIpnsRecordBytes(recordBytes);
285→        this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
286→      }
287→    } catch (error) {
288→      // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
289→      if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
290→        this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
291→      } else {
292→        throw error;
293→      }
294→    }
295→
296→    // Always check DB cache — it's written synchronously during publish
297→    // and may be ahead of the network (delegated routing can serve stale records)
298→    const cached = await this.folderIpnsRepository.findOne({
299→      where: { ipnsName },
300→    });
301→
302→    if (result && cached?.latestCid) {
303→      // Both sources available — prefer the one with the higher sequence number
304→      const networkSeq = BigInt(result.sequenceNumber);
305→      const dbSeq = BigInt(cached.sequenceNumber);
306→      if (dbSeq > networkSeq) {
307→        this.logger.log(
308→          `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
309→        );
310→        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
311→      }
312→      return result;
313→    }
314→
315→    if (result) {
316→      return result;
317→    }
318→
319→    // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
320→    if (cached?.latestCid) {
321→      this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
322→      return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
323→    }
324→
325→    return null;
326→  }
327→
328→  /**
329→   * Parse an IPNS record to extract CID and sequence number
330→   * Uses inline protobuf decoder — no external dependencies
331→   */
332→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
333→    cid: string;
334→    sequenceNumber: string;
335→    signatureV2?: string;
336→    data?: string;
337→    pubKey?: string;
338→  } {
339→    try {
340→      const record = parseIpnsRecord(recordBytes);
341→
342→      // Extract CID from the Value field (format: /ipfs/<cid>)
343→      const valuePath = record.value;
344→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
345→      if (!cidMatch) {
346→        this.logger.error('Failed to extract CID from IPNS record value');
347→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
348→      }
349→
350→      const cid = cidMatch[1];
351→      const sequenceNumber = String(record.sequence ?? 0n);
352→
353→      // Base64-encode signature fields if present
354→      const signatureV2 = record.signatureV2
355→        ? Buffer.from(record.signatureV2).toString('base64')
356→        : undefined;
357→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
358→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
359→
360→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
361→      return { cid, sequenceNumber, signatureV2, data, pubKey };
362→    } catch (error) {
363→      if (error instanceof HttpException) {
364→        throw error;
365→      }
366→      this.logger.error(`Failed to parse IPNS record: ${error}`);
367→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
368→    }
369→  }
370→}
