  1→/**
  2→ * IPNS Service - Record creation, publishing, and resolution
  3→ *
  4→ * Creates IPNS records locally using @cipherbox/crypto and publishes
  5→ * via the backend API relay to delegated-ipfs.dev.
  6→ */
  7→
  8→import {
  9→  createIpnsRecord,
 10→  marshalIpnsRecord,
 11→  verifyEd25519,
 12→  IPNS_SIGNATURE_PREFIX,
 13→  concatBytes,
 14→} from '@cipherbox/crypto';
 15→import {
 16→  ipnsControllerPublishRecord,
 17→  ipnsControllerPublishBatch,
 18→  ipnsControllerResolveRecord,
 19→} from '../api/ipns/ipns';
 20→import type { PublishIpnsEntryDtoRecordType } from '../api/models/publishIpnsEntryDtoRecordType';
 21→
 22→/**
 23→ * Create an IPNS record locally and publish via backend.
 24→ *
 25→ * The record is signed locally using the Ed25519 private key, then
 26→ * the backend relays it to the IPFS network via delegated routing.
 27→ *
 28→ * @param params.ipnsPrivateKey - Ed25519 private key (64 bytes in libp2p format)
 29→ * @param params.ipnsName - IPNS name (k51.../bafzaa... format)
 30→ * @param params.metadataCid - CID of the encrypted metadata blob
 31→ * @param params.sequenceNumber - Current sequence number (will be incremented before publish)
 32→ * @param params.encryptedIpnsPrivateKey - Hex ECIES-wrapped key for TEE (first publish only)
 33→ * @param params.keyEpoch - TEE key epoch (required with encryptedIpnsPrivateKey)
 34→ */
 35→export async function createAndPublishIpnsRecord(params: {
 36→  ipnsPrivateKey: Uint8Array;
 37→  ipnsName: string;
 38→  metadataCid: string;
 39→  sequenceNumber: bigint;
 40→  encryptedIpnsPrivateKey?: string;
 41→  keyEpoch?: number;
 42→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 43→  // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 44→  // 24 hour lifetime (will be republished by TEE every 3 hours)
 45→  const record = await createIpnsRecord(
 46→    params.ipnsPrivateKey,
 47→    `/ipfs/${params.metadataCid}`,
 48→    params.sequenceNumber,
 49→    24 * 60 * 60 * 1000 // 24 hours in ms
 50→  );
 51→
 52→  // 2. Marshal to bytes for transport
 53→  const recordBytes = marshalIpnsRecord(record);
 54→
 55→  // 3. Base64 encode for API transmission
 56→  const recordBase64 = btoa(String.fromCharCode(...recordBytes));
 57→
 58→  // 4. Call backend API to relay to IPFS network
 59→  const response = await ipnsControllerPublishRecord({
 60→    ipnsName: params.ipnsName,
 61→    record: recordBase64,
 62→    metadataCid: params.metadataCid,
 63→    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
 64→    keyEpoch: params.keyEpoch,
 65→  });
 66→
 67→  return {
 68→    success: response.success,
 69→    sequenceNumber: BigInt(response.sequenceNumber),
 70→  };
 71→}
 72→
 73→/**
 74→ * Batch publish multiple IPNS records in a single API call.
 75→ *
 76→ * Sends all records (folder and/or file) to the batch endpoint,
 77→ * which processes them with concurrency-limited parallelism.
 78→ * Partial success is allowed: individual failures do not fail the batch.
 79→ *
 80→ * @param records - Array of IPNS record payloads to publish
 81→ * @returns Success and failure counts
 82→ */
 83→export async function batchPublishIpnsRecords(
 84→  records: Array<{
 85→    ipnsName: string;
 86→    recordBase64: string;
 87→    metadataCid: string;
 88→    encryptedIpnsPrivateKey?: string;
 89→    keyEpoch?: number;
 90→    recordType?: 'folder' | 'file';
 91→  }>
 92→): Promise<{ totalSucceeded: number; totalFailed: number }> {
 93→  const response = await ipnsControllerPublishBatch({
 94→    records: records.map((r) => ({
 95→      ipnsName: r.ipnsName,
 96→      record: r.recordBase64,
 97→      metadataCid: r.metadataCid,
 98→      encryptedIpnsPrivateKey: r.encryptedIpnsPrivateKey,
 99→      keyEpoch: r.keyEpoch,
100→      recordType: r.recordType as PublishIpnsEntryDtoRecordType | undefined,
101→    })),
102→  });
103→
104→  return {
105→    totalSucceeded: response.totalSucceeded,
106→    totalFailed: response.totalFailed,
107→  };
108→}
109→
110→/**
111→ * Verify the Ed25519 signature on an IPNS record.
112→ * Per IPFS spec, the signature is over "ipns-signature:" + cborData.
113→ *
114→ * @param signatureV2 - base64 Ed25519 signature (64 bytes)
115→ * @param data - base64 CBOR data that was signed
116→ * @param pubKey - base64 raw Ed25519 public key (32 bytes)
117→ * @returns true if valid
118→ */
119→export async function verifyIpnsSignature(
120→  signatureV2: string,
121→  data: string,
122→  pubKey: string
123→): Promise<boolean> {
124→  const sigBytes = Uint8Array.from(atob(signatureV2), (c) => c.charCodeAt(0));
125→  const dataBytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
126→  const pubKeyBytes = Uint8Array.from(atob(pubKey), (c) => c.charCodeAt(0));
127→
128→  // Per IPFS IPNS spec, signature is over "ipns-signature:" + cborData
129→  const signedData = concatBytes(IPNS_SIGNATURE_PREFIX, dataBytes);
130→  return verifyEd25519(sigBytes, signedData, pubKeyBytes);
131→}
132→
133→/**
134→ * Resolve an IPNS name to its current CID and sequence number.
135→ *
136→ * Calls backend API which relays to delegated-ipfs.dev for resolution.
137→ * When the response includes IPNS signature data (from delegated routing),
138→ * verifies the Ed25519 signature before trusting the CID.
139→ *
140→ * @param ipnsName - IPNS name to resolve (k51.../bafzaa... format)
141→ * @returns Current CID, sequence number, and signature verification status, or null if not found
142→ */
143→export async function resolveIpnsRecord(
144→  ipnsName: string
145→): Promise<{ cid: string; sequenceNumber: bigint; signatureVerified: boolean } | null> {
146→  try {
147→    const response = await ipnsControllerResolveRecord({ ipnsName });
148→
149→    if (!response.success) {
150→      return null;
151→    }
152→
153→    // Verify IPNS signature if all signature fields are present
154→    let signatureVerified = false;
155→    if (response.signatureV2 && response.data && response.pubKey) {
156→      const valid = await verifyIpnsSignature(response.signatureV2, response.data, response.pubKey);
157→      if (!valid) {
158→        throw new Error('IPNS signature verification failed - record may be tampered');
159→      }
160→      signatureVerified = true;
161→    } else {
162→      console.warn('IPNS resolve returned without signature data, skipping verification');
163→    }
164→
165→    return {
166→      cid: response.cid,
167→      sequenceNumber: BigInt(response.sequenceNumber),
168→      signatureVerified,
169→    };
170→  } catch (error) {
171→    // 404 means IPNS name not found - return null
172→    // Other errors should propagate (including signature verification failures)
173→    if (error instanceof Error && (error as Error & { status?: number }).status === 404) {
174→      return null;
175→    }
176→    throw error;
177→  }
178→}
