 566→/**
 567→ * Add multiple files to a folder after successful upload (v2 batch).
 568→ *
 569→ * Creates FilePointer objects for all files, checks for name collisions,
 570→ * then publishes all N file IPNS records + 1 folder IPNS record via a
 571→ * single batch API call.
 572→ *
 573→ * @param params.parentFolderState - Parent folder to add files to
 574→ * @param params.files - Array of file data with pre-created IPNS records
 575→ * @returns Created file pointers and new sequence number
 576→ * @throws Error if any name collision exists
 577→ */
 578→export async function addFilesToFolder(params: {
 579→  parentFolderState: FolderNode;
 580→  files: Array<{
 581→    fileId: string;
 582→    name: string;
 583→    fileIpnsRecord: FileIpnsRecordPayload;
 584→    ipnsPrivateKeyEncrypted: string;
 585→  }>;
 586→}): Promise<{ filePointers: FilePointer[]; newSequenceNumber: bigint }> {
 587→  // 1. Build a set of existing child names for collision detection
 588→  const existingNames = new Set(params.parentFolderState.children.map((c) => c.name));
 589→
 590→  // 2. Create FilePointer for each file, checking collisions
 591→  const filePointers: FilePointer[] = [];
 592→  const now = Date.now();
 593→
 594→  for (const file of params.files) {
 595→    if (existingNames.has(file.name)) {
 596→      throw new Error(`A file with name "${file.name}" already exists`);
 597→    }
 598→    existingNames.add(file.name);
 599→
 600→    const filePointer: FilePointer = {
 601→      type: 'file',
 602→      id: file.fileId,
 603→      name: file.name,
 604→      fileMetaIpnsName: file.fileIpnsRecord.ipnsName,
 605→      ipnsPrivateKeyEncrypted: file.ipnsPrivateKeyEncrypted,
 606→      createdAt: now,
 607→      modifiedAt: now,
 608→    };
 609→    filePointers.push(filePointer);
 610→  }
 611→
 612→  // 3. Build updated children array
 613→  const children: FolderChild[] = [...params.parentFolderState.children, ...filePointers];
 614→
 615→  // 4. Build folder IPNS record
 616→  const folderResult = await buildFolderIpnsRecord({
 617→    children,
 618→    folderKey: params.parentFolderState.folderKey,
 619→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 620→    ipnsName: params.parentFolderState.ipnsName,
 621→    sequenceNumber: params.parentFolderState.sequenceNumber,
 622→  });
 623→
 624→  // 5. Batch publish: all N file IPNS records + 1 folder IPNS record (single API call)
 625→  const allRecords = [
 626→    ...params.files.map((f) => ({ ...f.fileIpnsRecord, recordType: 'file' as const })),
 627→    folderResult.record,
 628→  ];
 629→  const publishResult = await batchPublishIpnsRecords(allRecords);
 630→
 631→  if (publishResult.totalFailed > 0) {
 632→    console.error(
 633→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
 634→    );
 635→    throw new Error('Failed to publish one or more IPNS records');
 636→  }
 637→
 638→  return { filePointers, newSequenceNumber: folderResult.newSequenceNumber };
 639→}
