 641→/**
 642→ * Replace file content in v2 metadata (content update).
 643→ *
 644→ * THIS IS THE PRIMARY BENEFIT OF PER-FILE IPNS: content updates publish
 645→ * ONLY the file's IPNS record. The folder metadata is NOT touched because
 646→ * the FilePointer still points to the same fileMetaIpnsName, which now
 647→ * resolves to the updated content.
 648→ *
 649→ * @param params.fileId - ID of file to update
 650→ * @param params.fileIpnsRecord - Updated file IPNS record from updateFileMetadata
 651→ * @param params.parentFolderState - Parent folder (used only to find the FilePointer)
 652→ * @returns Void -- no folder metadata update needed
 653→ * @throws Error if file not found
 654→ */
 655→export async function replaceFileInFolder(params: {
 656→  fileId: string;
 657→  fileIpnsRecord: FileIpnsRecordPayload;
 658→  parentFolderState: FolderNode;
 659→}): Promise<void> {
 660→  // 1. Verify file exists in parent's children
 661→  const fileExists = params.parentFolderState.children.some(
