 663→  );
 664→
 665→  if (!fileExists) throw new Error('File not found');
 666→
 667→  // 2. Publish ONLY the file IPNS record (folder metadata untouched!)
 668→  // This is the key optimization: content update does NOT modify folder metadata.
 669→  const publishResult = await batchPublishIpnsRecords([
 670→    { ...params.fileIpnsRecord, recordType: 'file' },
 671→  ]);
 672→
 673→  if (publishResult.totalFailed > 0) {
 674→    throw new Error('Failed to publish file IPNS record');
 675→  }
