 678→/**
 679→ * Calculate the maximum depth of a folder's subtree.
 680→ *
 681→ * Used to check if moving a folder would exceed the depth limit.
 682→ *
 683→ * @param folderId - Folder ID to calculate subtree depth for
 684→ * @param folders - Current folder tree
 685→ * @returns Maximum depth in the subtree (0 if folder has no children)
 686→ */
 687→export function calculateSubtreeDepth(
 688→  folderId: string,
 689→  folders: Record<string, FolderNode>
 690→): number {
 691→  const folder = folders[folderId];
 692→  if (!folder) return 0;
 693→
 694→  let maxChildDepth = 0;
 695→  for (const child of folder.children) {
 696→    if (child.type === 'folder') {
 697→      const childDepth = 1 + calculateSubtreeDepth(child.id, folders);
 698→      maxChildDepth = Math.max(maxChildDepth, childDepth);
 699→    }
 700→  }
 701→
 702→  return maxChildDepth;
 703→}
