 705→/**
 706→ * Check if a folder is a descendant of a potential ancestor.
 707→ *
 708→ * Used to prevent moving a folder into itself or its descendants.
 709→ *
 710→ * @param folderId - Folder to check
 711→ * @param potentialAncestorId - Potential ancestor folder ID
 712→ * @param folders - Current folder tree
 713→ * @returns true if folderId is a descendant of potentialAncestorId
 714→ */
 715→export function isDescendantOf(
 716→  folderId: string,
 717→  potentialAncestorId: string,
 718→  folders: Record<string, FolderNode>
 719→): boolean {
 720→  let currentId: string | null = folderId;
 721→
 722→  while (currentId !== null) {
 723→    if (currentId === potentialAncestorId) return true;
 724→    const currentFolder: FolderNode | undefined = folders[currentId];
 725→    if (!currentFolder) break;
 726→    currentId = currentFolder.parentId;
 727→  }
 728→
 729→  return false;
 730→}
