 732→/**
 733→ * Move a folder from one parent to another.
 734→ *
 735→ * Uses add-before-remove pattern to prevent data loss on failure.
 736→ * Validates depth limit and prevents moving folder into itself.
 737→ *
 738→ * @param params.folderId - ID of folder to move
 739→ * @param params.sourceFolderState - Current parent folder
 740→ * @param params.destFolderState - Destination parent folder
 741→ * @param params.folders - Full folder tree (for depth calculation)
 742→ * @throws Error if folder not found, name collision, depth limit exceeded,
 743→ *         or attempting to move folder into itself/descendant
 744→ */
 745→export async function moveFolder(params: {
 746→  folderId: string;
 747→  sourceFolderState: FolderNode;
 748→  destFolderState: FolderNode;
 749→  folders: Record<string, FolderNode>;
 750→}): Promise<void> {
 751→  // 1. Find folder in source
 752→  const folder = params.sourceFolderState.children.find(
 753→    (c) => c.type === 'folder' && c.id === params.folderId
 754→  ) as FolderEntry | undefined;
 755→
 756→  if (!folder) throw new Error('Folder not found');
 757→
 758→  // 2. Check name collision in destination
 759→  const nameExists = params.destFolderState.children.some((c) => c.name === folder.name);
 760→  if (nameExists) throw new Error('An item with this name already exists in destination');
 761→
 762→  // 3. Check depth limit (20 levels max)
 763→  const destDepth = getDepth(params.destFolderState.id, params.folders);
 764→  const folderSubtreeDepth = calculateSubtreeDepth(params.folderId, params.folders);
 765→  if (destDepth + 1 + folderSubtreeDepth > MAX_FOLDER_DEPTH) {
 766→    throw new Error(`Cannot move: would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`);
 767→  }
 768→
 769→  // 4. Prevent moving folder into itself or its descendants
 770→  if (isDescendantOf(params.destFolderState.id, params.folderId, params.folders)) {
 771→    throw new Error('Cannot move folder into itself or its subfolder');
 772→  }
 773→
 774→  // 5. ADD to destination FIRST (add-before-remove pattern)
 775→  const destChildren: FolderChild[] = [
 776→    ...params.destFolderState.children,
 777→    {
 778→      ...folder,
 779→      modifiedAt: Date.now(),
 780→    },
 781→  ];
 782→
 783→  await updateFolderMetadata({
 784→    folderId: params.destFolderState.id,
 785→    children: destChildren,
 786→    folderKey: params.destFolderState.folderKey,
 787→    ipnsPrivateKey: params.destFolderState.ipnsPrivateKey,
 788→    ipnsName: params.destFolderState.ipnsName,
 789→    sequenceNumber: params.destFolderState.sequenceNumber,
 790→  });
 791→
 792→  // 6. REMOVE from source AFTER destination confirmed
 793→  const sourceChildren = params.sourceFolderState.children.filter(
 794→    (c) => !(c.type === 'folder' && c.id === params.folderId)
 795→  );
 796→
 797→  await updateFolderMetadata({
 798→    folderId: params.sourceFolderState.id,
 799→    children: sourceChildren,
 800→    folderKey: params.sourceFolderState.folderKey,
 801→    ipnsPrivateKey: params.sourceFolderState.ipnsPrivateKey,
 802→    ipnsName: params.sourceFolderState.ipnsName,
 803→    sequenceNumber: params.sourceFolderState.sequenceNumber,
 804→  });
 805→}
