 870→ *
 871→ * Updates the FilePointer's name in the parent's metadata and publishes
 872→ * an updated IPNS record for the parent folder.
 873→ * File rename does NOT touch the file's own IPNS record -- only folder metadata.
 874→ *
 875→ * @param params.fileId - ID of file to rename
 876→ * @param params.newName - New name for the file
 877→ * @param params.parentFolderState - Parent folder containing this file
 878→ * @throws Error if file not found or name collision exists
 879→ */
 880→export async function renameFile(params: {
 881→  fileId: string;
 882→  newName: string;
 883→  parentFolderState: FolderNode;
 884→}): Promise<void> {
 885→  const children = [...params.parentFolderState.children];
 886→  const fileIndex = children.findIndex((c) => c.type === 'file' && c.id === params.fileId);
 887→
 888→  if (fileIndex === -1) throw new Error('File not found');
 889→
