 911→/**
 912→ * Fetch and decrypt folder metadata from IPFS.
 913→ *
 914→ * Used for sync operations when remote IPNS resolves to a different CID.
 915→ * Fetches the encrypted metadata blob from IPFS and decrypts it with the folder key.
 916→ * @param cid - IPFS CID of the encrypted metadata blob
 917→ * @param folderKey - Decrypted AES-256 folder key
 918→ * @returns Decrypted folder metadata (v2)
 919→ * @throws Error if fetch or decryption fails
 920→ */
 921→export async function fetchAndDecryptMetadata(
 922→  cid: string,
 923→  folderKey: Uint8Array
 924→): Promise<FolderMetadata> {
 925→  // 1. Fetch encrypted metadata blob from IPFS
 926→  const encryptedBytes = await fetchFromIpfs(cid);
 927→
 928→  // 2. Parse as JSON to get EncryptedFolderMetadata (contains iv and data fields)
 929→  const encryptedJson = new TextDecoder().decode(encryptedBytes);
 930→  const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
 931→
 932→  // 3. Decrypt using folder key
 933→  const metadata = await decryptFolderMetadata(encrypted, folderKey);
 934→
 935→  return metadata;
 936→}
