 13→/**
 14→ * React hook for folder CRUD operations (create, rename, move, delete).
 15→ *
 16→ * Returns loading/error state and operation callbacks.
 17→ */
 18→export function useFolderMutations() {
 19→  const [state, setState] = useState<FolderOperationState>({
 20→    isLoading: false,
 21→    error: null,
 22→  });
 23→
 24→  /**
 25→   * Create a new folder.
 26→   *
 27→   * @param name - Folder name
 28→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 29→   * @returns Created folder entry
 30→   * @throws Error if depth limit exceeded or creation fails
 31→   */
 32→  const handleCreate = useCallback(
 33→    async (name: string, parentId: string | null): Promise<FolderEntry> => {
 34→      setState({ isLoading: true, error: null });
 35→      try {
 36→        const folders = useFolderStore.getState().folders;
 37→        const vault = useVaultStore.getState();
 38→        const auth = useAuthStore.getState();
 39→
 40→        // Validate depth limit before creating (FOLD-03)
 41→        const parentDepth = folderService.getDepth(parentId, folders);
 42→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 43→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 44→        }
 45→
 46→        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
 47→        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
 48→        if (!auth.vaultKeypair) {
 49→          throw new Error('No ECIES keypair available - please log in again');
 50→        }
 51→        const userPublicKey = auth.vaultKeypair.publicKey;
 52→
 53→        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
 54→        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 55→          await folderService.createFolder({
 56→            parentFolderId: parentId,
 57→            name,
 58→            userPublicKey,
 59→            folders,
 60→          });
 61→
 62→        // Get parent folder state
 63→        const parentFolder =
 64→          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);
 65→
 66→        if (!parentFolder) {
 67→          throw new Error('Parent folder not found or vault not initialized');
 68→        }
 69→
 70→        // Add to parent's children
 71→        const newChildren = [...parentFolder.children, folder];
 72→
 73→        // Update parent folder metadata and publish IPNS
 74→        await folderService.updateFolderMetadata({
 75→          folderId: parentFolder.id,
 76→          children: newChildren,
 77→          folderKey: parentFolder.folderKey,
 78→          ipnsPrivateKey: parentFolder.ipnsPrivateKey,
 79→          ipnsName: parentFolder.ipnsName,
 80→          sequenceNumber: parentFolder.sequenceNumber,
 81→        });
 82→
 83→        // First publish for the new folder's own IPNS record with TEE-encrypted key
 84→        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
 85→        await folderService.updateFolderMetadata({
 86→          folderId: folder.id,
 87→          children: [],
 88→          folderKey,
 89→          ipnsPrivateKey,
 90→          ipnsName: folder.ipnsName,
 91→          sequenceNumber: 0n,
 92→          encryptedIpnsPrivateKey,
 93→          keyEpoch,
 94→        });
 95→
 96→        // Update local state - add new folder to tree
 97→        useFolderStore.getState().updateFolderChildren(parentFolder.id, newChildren);
 98→
 99→        // Also add the new folder node to the store (with its decrypted keys)
100→        const newFolderNode: FolderNode = {
101→          id: folder.id,
102→          name: folder.name,
103→          ipnsName: folder.ipnsName,
104→          parentId: parentFolder.id,
105→          children: [],
106→          isLoaded: true,
107→          isLoading: false,
108→          sequenceNumber: 0n,
109→          folderKey,
110→          ipnsPrivateKey,
111→        };
112→        useFolderStore.getState().setFolder(newFolderNode);
113→
114→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
115→        reWrapForRecipients({
116→          folderIpnsName: parentFolder.ipnsName,
117→          folders: useFolderStore.getState().folders,
118→          currentFolderId: parentFolder.id,
119→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
120→        }).catch((err) => {
121→          console.warn('[share] Post-create subfolder re-wrapping failed:', err);
122→        });
123→
124→        setState({ isLoading: false, error: null });
125→        return folder;
126→      } catch (err) {
127→        const error = err instanceof Error ? err.message : 'Failed to create folder';
128→        setState({ isLoading: false, error });
129→        throw err;
130→      }
131→    },
132→    []
133→  );
