135→  /**
136→   * Rename a file or folder.
137→   *
138→   * @param itemId - ID of item to rename
139→   * @param itemType - 'file' or 'folder'
140→   * @param newName - New name
141→   * @param parentId - Parent folder ID
142→   */
143→  const handleRename = useCallback(
144→    async (
145→      itemId: string,
146→      itemType: 'file' | 'folder',
147→      newName: string,
148→      parentId: string
149→    ): Promise<void> => {
150→      setState({ isLoading: true, error: null });
151→      try {
152→        const folders = useFolderStore.getState().folders;
153→        const vault = useVaultStore.getState();
154→
155→        // Get parent folder state
156→        const parentFolder =
157→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
158→
159→        if (!parentFolder) throw new Error('Parent folder not found');
160→
161→        if (itemType === 'folder') {
162→          await folderService.renameFolder({
163→            folderId: itemId,
164→            newName,
165→            parentFolderState: parentFolder,
166→          });
167→
168→          // Update local folder state name
169→          useFolderStore.getState().updateFolderName(itemId, newName);
170→        } else {
171→          await folderService.renameFile({
172→            fileId: itemId,
173→            newName,
174→            parentFolderState: parentFolder,
175→          });
176→        }
177→
178→        // Update parent's children with new name
179→        const updatedChildren = parentFolder.children.map((child) => {
180→          if (child.id === itemId) {
181→            return { ...child, name: newName, modifiedAt: Date.now() };
182→          }
183→          return child;
184→        });
185→        useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
186→
187→        setState({ isLoading: false, error: null });
188→      } catch (err) {
189→        const error = err instanceof Error ? err.message : 'Failed to rename';
190→        setState({ isLoading: false, error });
191→        throw err;
192→      }
193→    },
194→    []
