197→  /**
198→   * Move a file or folder to a different parent.
199→   *
200→   * @param itemId - ID of item to move
201→   * @param itemType - 'file' or 'folder'
202→   * @param sourceParentId - Current parent folder ID
203→   * @param destParentId - Destination parent folder ID
204→   */
205→  const handleMove = useCallback(
206→    async (
207→      itemId: string,
208→      itemType: 'file' | 'folder',
209→      sourceParentId: string,
210→      destParentId: string
211→    ): Promise<void> => {
212→      setState({ isLoading: true, error: null });
213→      try {
214→        const folders = useFolderStore.getState().folders;
215→        const vault = useVaultStore.getState();
216→
217→        // Get source and destination folder states
218→        const sourceFolder =
219→          sourceParentId === 'root' ? getRootFolderState(vault, folders) : folders[sourceParentId];
220→
221→        const destFolder =
222→          destParentId === 'root' ? getRootFolderState(vault, folders) : folders[destParentId];
223→
224→        if (!sourceFolder || !destFolder) {
225→          throw new Error('Source or destination folder not found');
226→        }
227→
228→        if (itemType === 'folder') {
229→          await folderService.moveFolder({
230→            folderId: itemId,
231→            sourceFolderState: sourceFolder,
232→            destFolderState: destFolder,
233→            folders,
234→          });
235→
236→          // Update the moved folder's parentId in local state
237→          const movedFolder = folders[itemId];
238→          if (movedFolder) {
239→            useFolderStore.getState().setFolder({
240→              ...movedFolder,
241→              parentId: destParentId,
242→            });
243→          }
244→        } else {
245→          await folderService.moveFile({
246→            fileId: itemId,
247→            sourceFolderState: sourceFolder,
248→            destFolderState: destFolder,
249→          });
250→        }
251→
252→        // Update source folder's children (remove item)
253→        const updatedSourceChildren = sourceFolder.children.filter((c) => c.id !== itemId);
254→        useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
255→
256→        // Update dest folder's children (add item)
257→        const movedItem = sourceFolder.children.find((c) => c.id === itemId);
258→        if (movedItem) {
259→          const updatedDestChildren = [
260→            ...destFolder.children,
261→            { ...movedItem, modifiedAt: Date.now() },
262→          ];
263→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
264→        }
265→
266→        setState({ isLoading: false, error: null });
267→      } catch (err) {
268→        const error = err instanceof Error ? err.message : 'Failed to move';
269→        setState({ isLoading: false, error });
270→        throw err;
271→      }
272→    },
273→    []
274→  );
