276→  /**
277→   * Move multiple files/folders to a destination in a single batch.
278→   *
279→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
280→   * and once for the source (2 total), regardless of how many items are moved.
281→   *
282→   * @param items - Array of { id, type } to move
283→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
284→   * @param destParentId - Destination parent folder ID
285→   */
286→  const handleMoveItems = useCallback(
287→    async (
288→      items: Array<{ id: string; type: 'file' | 'folder' }>,
289→      sourceParentId: string,
290→      destParentId: string
291→    ): Promise<void> => {
292→      setState({ isLoading: true, error: null });
293→      try {
294→        const folders = useFolderStore.getState().folders;
295→        const vault = useVaultStore.getState();
296→
297→        const sourceFolder =
298→          sourceParentId === 'root' ? getRootFolderState(vault, folders) : folders[sourceParentId];
299→        const destFolder =
300→          destParentId === 'root' ? getRootFolderState(vault, folders) : folders[destParentId];
301→
302→        if (!sourceFolder || !destFolder) {
303→          throw new Error('Source or destination folder not found');
304→        }
305→
306→        const itemIds = new Set(items.map((i) => i.id));
307→        const movedChildren = sourceFolder.children.filter((c) => itemIds.has(c.id));
308→        const now = Date.now();
309→
310→        // Validate all items
311→        const batchNames = new Set<string>();
312→        for (const child of movedChildren) {
313→          // Intra-batch duplicate name check
314→          if (batchNames.has(child.name)) {
315→            throw new Error(`Multiple selected items share the name "${child.name}"`);
316→          }
317→          batchNames.add(child.name);
318→
319→          // Name collision check against destination
320→          const nameExists = destFolder.children.some((c) => c.name === child.name);
321→          if (nameExists) {
322→            throw new Error(`An item named "${child.name}" already exists in the destination`);
323→          }
324→
325→          if (child.type === 'folder') {
326→            // Prevent moving folder into itself or descendant
327→            if (folderService.isDescendantOf(destFolder.id, child.id, folders)) {
328→              throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
329→            }
330→
331→            // Depth limit check
332→            const destDepth = folderService.getDepth(destFolder.id, folders);
333→            const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
334→            if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
335→              throw new Error(
336→                `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
337→              );
338→            }
339→          }
340→        }
341→
342→        // ADD all to destination FIRST (add-before-remove pattern)
343→        const destChildren = [
344→          ...destFolder.children,
345→          ...movedChildren.map((c) => ({ ...c, modifiedAt: now })),
346→        ];
347→
348→        const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
349→          folderId: destFolder.id,
350→          children: destChildren,
351→          folderKey: destFolder.folderKey,
352→          ipnsPrivateKey: destFolder.ipnsPrivateKey,
353→          ipnsName: destFolder.ipnsName,
354→          sequenceNumber: destFolder.sequenceNumber,
355→        });
356→
357→        // REMOVE all from source AFTER destination confirmed
358→        const sourceChildren = sourceFolder.children.filter((c) => !itemIds.has(c.id));
359→
360→        const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
361→          folderId: sourceFolder.id,
362→          children: sourceChildren,
363→          folderKey: sourceFolder.folderKey,
364→          ipnsPrivateKey: sourceFolder.ipnsPrivateKey,
365→          ipnsName: sourceFolder.ipnsName,
366→          // Re-read sequence in case source === dest parent was updated above
367→          sequenceNumber: sourceFolder.id === destFolder.id ? destSeq : sourceFolder.sequenceNumber,
368→        });
369→
370→        // Update local state
371→        const store = useFolderStore.getState();
372→        store.updateFolderChildren(sourceParentId, sourceChildren);
373→        store.updateFolderChildren(destParentId, destChildren);
374→        store.updateFolderSequence(destParentId, destSeq);
375→        store.updateFolderSequence(sourceParentId, sourceSeq);
376→
377→        for (const item of items) {
378→          if (item.type === 'folder') {
379→            const movedFolder = folders[item.id];
380→            if (movedFolder) {
381→              store.setFolder({ ...movedFolder, parentId: destParentId });
382→            }
383→          }
384→        }
385→
386→        setState({ isLoading: false, error: null });
387→      } catch (err) {
388→        const error = err instanceof Error ? err.message : 'Failed to move items';
389→        setState({ isLoading: false, error });
390→        throw err;
391→      }
392→    },
393→    []
394→  );
