402→   */
403→  const handleDelete = useCallback(
404→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
405→      setState({ isLoading: true, error: null });
406→      try {
407→        const folders = useFolderStore.getState().folders;
408→        const vault = useVaultStore.getState();
409→
410→        // Get parent folder state
411→        const parentFolder =
412→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
413→
414→        if (!parentFolder) throw new Error('Parent folder not found');
415→
416→        if (itemType === 'folder') {
417→          await folderService.deleteFolder({
418→            folderId: itemId,
419→            parentFolderState: parentFolder,
420→            getFolderState: (id) => folders[id],
421→            unpinCid: unpinFromIpfs,
422→          });
423→
424→          // Remove folder from local state
425→          useFolderStore.getState().removeFolder(itemId);
426→        } else {
427→          await folderService.deleteFileFromFolder({
428→            fileId: itemId,
429→            parentFolderState: parentFolder,
430→          });
431→        }
432→
433→        // Update parent's children (remove item)
434→        const updatedChildren = parentFolder.children.filter((c) => c.id !== itemId);
435→        useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
436→
437→        setState({ isLoading: false, error: null });
438→      } catch (err) {
439→        const error = err instanceof Error ? err.message : 'Failed to delete';
440→        setState({ isLoading: false, error });
441→        throw err;
442→      }
443→    },
444→    []
445→  );
