447→  /**
448→   * Delete multiple files/folders in a single IPNS publish.
449→   *
450→   * Removes all items from parent's children array, collects CIDs to unpin,
451→   * then publishes metadata and IPNS once for the entire batch.
452→   *
453→   * @param items - Array of { id, type } to delete
454→   * @param parentId - Parent folder ID (all items must share the same parent)
455→   */
456→  const handleDeleteItems = useCallback(
457→    async (
458→      items: Array<{ id: string; type: 'file' | 'folder' }>,
459→      parentId: string
460→    ): Promise<void> => {
461→      setState({ isLoading: true, error: null });
462→      try {
463→        const folders = useFolderStore.getState().folders;
464→        const vault = useVaultStore.getState();
465→
466→        const parentFolder =
467→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
468→
469→        if (!parentFolder) throw new Error('Parent folder not found');
470→
471→        const itemIds = new Set(items.map((i) => i.id));
472→
473→        // Collect nested folder IDs to remove from store
474→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
475→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
476→        const folderIdsToRemove: string[] = [];
477→
478→        const collectFolderIds = (folderId: string) => {
479→          folderIdsToRemove.push(folderId);
480→          const folder = folders[folderId];
481→          if (!folder) return;
482→          for (const child of folder.children) {
483→            if (child.type === 'folder') {
484→              collectFolderIds(child.id);
485→            }
486→          }
487→        };
488→
489→        for (const item of items) {
490→          if (item.type === 'folder') {
491→            collectFolderIds(item.id);
492→          }
493→        }
494→
495→        // Remove all items from parent's children in one pass
496→        const updatedChildren = parentFolder.children.filter((c) => !itemIds.has(c.id));
497→
498→        // Single IPNS publish for the entire batch
499→        await folderService.updateFolderMetadata({
500→          folderId: parentFolder.id,
501→          children: updatedChildren,
502→          folderKey: parentFolder.folderKey,
503→          ipnsPrivateKey: parentFolder.ipnsPrivateKey,
504→          ipnsName: parentFolder.ipnsName,
505→          sequenceNumber: parentFolder.sequenceNumber,
506→        });
507→
508→        // Update local state -- remove all nested folders from store
509→        const store = useFolderStore.getState();
510→        store.updateFolderChildren(parentId, updatedChildren);
511→        for (const folderId of folderIdsToRemove) {
512→          store.removeFolder(folderId);
513→        }
514→
515→        setState({ isLoading: false, error: null });
516→      } catch (err) {
517→        const error = err instanceof Error ? err.message : 'Failed to delete items';
518→        setState({ isLoading: false, error });
519→        throw err;
520→      }
521→    },
522→    []
523→  );
524→
525→  return {
526→    ...state,
527→    createFolder: handleCreate,
528→    renameItem: handleRename,
529→    moveItem: handleMove,
530→    moveItems: handleMoveItems,
531→    deleteItem: handleDelete,
532→    deleteItems: handleDeleteItems,
533→  };
534→}
