20→export function getRootFolderState(
21→  vaultStore: ReturnType<typeof useVaultStore.getState>,
22→  folders: Record<string, FolderNode>
23→): FolderNode | null {
24→  if (!vaultStore.rootFolderKey || !vaultStore.rootIpnsKeypair || !vaultStore.rootIpnsName) {
25→    return null;
26→  }
27→
28→  // If we have an explicit root folder in the tree, use it
29→  const existingRoot = folders['root'];
30→  if (existingRoot) return existingRoot;
31→
32→  // Otherwise construct from vault state
33→  return {
34→    id: 'root',
35→    name: 'My Vault',
36→    ipnsName: vaultStore.rootIpnsName,
37→    parentId: null,
38→    children: [],
39→    isLoaded: false,
40→    isLoading: false,
41→    sequenceNumber: 0n,
42→    folderKey: vaultStore.rootFolderKey,
43→    ipnsPrivateKey: vaultStore.rootIpnsKeypair.privateKey,
44→  };
