249→    /// Delete a file from a directory.
250→    pub fn handle_unlink(
251→        fs: &mut CipherBoxFS,
252→        parent: u64,
253→        name: &OsStr,
254→        reply: ReplyEmpty,
255→    ) {
256→        let name_str = match name.to_str() {
257→            Some(n) => n,
258→            None => {
259→                reply.error(libc::ENOENT);
260→                return;
261→            }
262→        };
263→
264→        let child_ino = match fs.inodes.find_child(parent, name_str) {
265→            Some(ino) => ino,
266→            None => {
267→                reply.error(libc::ENOENT);
268→                return;
269→            }
270→        };
271→
272→        let cid_to_unpin = match fs.inodes.get(child_ino) {
273→            Some(inode) => match &inode.kind {
274→                InodeKind::File { cid, .. } => {
275→                    if cid.is_empty() { None } else { Some(cid.clone()) }
276→                }
277→                _ => {
278→                    reply.error(libc::EISDIR);
279→                    return;
280→                }
281→            },
282→            None => {
283→                reply.error(libc::ENOENT);
284→                return;
285→            }
286→        };
287→
288→        log::debug!("unlink: {} from parent {}", name_str, parent);
289→
290→        fs.inodes.remove(child_ino);
291→
292→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
293→            parent_inode.attr.mtime = SystemTime::now();
294→            parent_inode.attr.ctime = SystemTime::now();
295→        }
296→
297→        if let Err(e) = fs.update_folder_metadata(parent) {
298→            log::error!("Failed to update folder metadata after unlink: {}", e);
299→        }
300→
301→        if let Some(cid) = cid_to_unpin {
302→            let api = fs.api.clone();
303→            fs.rt.spawn(async move {
304→                if let Err(e) = crate::api::ipfs::unpin_content(&api, &cid).await {
305→                    log::debug!("Background unpin failed for {}: {}", cid, e);
306→                }
307→            });
308→        }
309→
310→        reply.ok();
311→    }
