524→    /// Remove an empty directory.
525→    pub fn handle_rmdir(
526→        fs: &mut CipherBoxFS,
527→        parent: u64,
528→        name: &OsStr,
529→        reply: ReplyEmpty,
530→    ) {
531→        let name_str = match name.to_str() {
532→            Some(n) => n,
533→            None => {
534→                reply.error(libc::ENOENT);
535→                return;
536→            }
537→        };
538→
539→        let child_ino = match fs.inodes.find_child(parent, name_str) {
540→            Some(ino) => ino,
541→            None => {
542→                reply.error(libc::ENOENT);
543→                return;
544→            }
545→        };
546→
547→        let cid_to_unpin = match fs.inodes.get(child_ino) {
548→            Some(inode) => {
549→                match &inode.kind {
550→                    InodeKind::Folder { ipns_name, .. } => {
551→                        if let Some(ref children) = inode.children {
552→                            if !children.is_empty() {
553→                                reply.error(libc::ENOTEMPTY);
554→                                return;
555→                            }
556→                        }
557→                        fs.metadata_cache.get(ipns_name)
558→                            .map(|cached| cached.cid.clone())
559→                    }
560→                    _ => {
561→                        reply.error(libc::ENOTDIR);
562→                        return;
563→                    }
564→                }
565→            }
566→            None => {
567→                reply.error(libc::ENOENT);
568→                return;
569→            }
570→        };
571→
572→        log::debug!("rmdir: {} from parent {}", name_str, parent);
573→
574→        fs.inodes.remove(child_ino);
575→
576→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
577→            parent_inode.attr.mtime = SystemTime::now();
578→            parent_inode.attr.ctime = SystemTime::now();
579→        }
580→
581→        if let Err(e) = fs.update_folder_metadata(parent) {
582→            log::error!("Failed to update folder metadata after rmdir: {}", e);
583→        }
584→
585→        if let Some(cid) = cid_to_unpin {
586→            let api = fs.api.clone();
587→            fs.rt.spawn(async move {
588→                if let Err(e) = crate::api::ipfs::unpin_content(&api, &cid).await {
589→                    log::debug!("Background unpin failed for {}: {}", cid, e);
590→                }
591→            });
592→        }
593→
594→        reply.ok();
595→    }
