597→    /// Rename or move a file/folder.
598→    pub fn handle_rename(
599→        fs: &mut CipherBoxFS,
600→        parent: u64,
601→        name: &OsStr,
602→        newparent: u64,
603→        newname: &OsStr,
604→        reply: ReplyEmpty,
605→    ) {
606→        log::debug!(
607→            "rename: {:?} (parent {}) -> {:?} (parent {})",
608→            name, parent, newname, newparent,
609→        );
610→        let name_str = match name.to_str() {
611→            Some(n) => n,
612→            None => {
613→                reply.error(libc::EINVAL);
614→                return;
615→            }
616→        };
617→        let newname_str = match newname.to_str() {
618→            Some(n) => n,
619→            None => {
620→                reply.error(libc::EINVAL);
621→                return;
622→            }
623→        };
624→
625→        // Find source inode (with FUSE-T truncated name fallback)
626→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
627→            Some(ino) => (ino, name_str.to_string()),
628→            None => {
629→                let parent_inode = match fs.inodes.get(parent) {
630→                    Some(i) => i,
631→                    None => {
632→                        reply.error(libc::ENOENT);
633→                        return;
634→                    }
635→                };
636→                let children = parent_inode.children.clone().unwrap_or_default();
637→                let mut matches: Vec<(u64, String)> = Vec::new();
638→                for &child_ino in &children {
639→                    if let Some(child) = fs.inodes.get(child_ino) {
640→                        if is_platform_special(&child.name) {
641→                            continue;
642→                        }
643→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
644→                            matches.push((child_ino, child.name.clone()));
645→                        }
646→                    }
647→                }
648→                if matches.len() == 1 {
649→                    log::debug!(
650→                        "rename suffix-match: truncated {:?} matched full name {:?}",
651→                        name_str, matches[0].1
652→                    );
653→                    (matches[0].0, matches[0].1.clone())
654→                } else {
655→                    log::debug!(
656→                        "rename failed: {:?} not found (suffix matches: {})",
657→                        name_str, matches.len()
658→                    );
659→                    reply.error(libc::ENOENT);
660→                    return;
661→                }
662→            }
663→        };
664→
665→        let name_str = &actual_name;
666→
667→        log::debug!(
668→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
669→            name_str, source_ino, parent, newname_str, newparent,
670→        );
671→
672→        // If destination exists, handle replacement
673→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
674→            // Self-replace (rename "a" to "a" in same dir): no-op
675→            if dest_ino == source_ino {
676→                reply.ok();
677→                return;
678→            }
679→
680→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
681→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
682→                let source_is_dir = fs.inodes.get(source_ino)
683→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
684→                    .unwrap_or(false);
685→                let dest_is_dir = matches!(
686→                    dest_inode.kind,
687→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
688→                );
689→                if source_is_dir && !dest_is_dir {
690→                    reply.error(libc::ENOTDIR);
691→                    return;
692→                }
693→                if !source_is_dir && dest_is_dir {
694→                    reply.error(libc::EISDIR);
695→                    return;
696→                }
697→
698→                match &dest_inode.kind {
699→                    InodeKind::Folder { .. } => {
700→                        if let Some(ref children) = dest_inode.children {
701→                            if !children.is_empty() {
702→                                reply.error(libc::ENOTEMPTY);
703→                                return;
704→                            }
705→                        }
706→                    }
707→                    InodeKind::File { cid, .. } => {
708→                        if !cid.is_empty() {
709→                            let cid_clone = cid.clone();
710→                            let api = fs.api.clone();
711→                            fs.rt.spawn(async move {
712→                                let _ = crate::api::ipfs::unpin_content(
713→                                    &api, &cid_clone,
714→                                ).await;
715→                            });
716→                        }
717→                    }
718→                    _ => {}
719→                }
720→            }
721→            fs.inodes.remove(dest_ino);
722→        }
723→
724→        // Remove source from old parent's name index (NFC-normalized)
725→        {
726→            use unicode_normalization::UnicodeNormalization;
727→            let nfc_key: String = name_str.nfc().collect();
728→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
729→        }
730→
731→        // Update the source inode's name and parent
732→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
733→            inode.name = newname_str.to_string();
734→            inode.parent_ino = newparent;
735→            inode.attr.ctime = SystemTime::now();
736→        }
737→
738→        // Update the name lookup index for the new location (NFC-normalized)
739→        {
740→            use unicode_normalization::UnicodeNormalization;
741→            let nfc_key: String = newname_str.nfc().collect();
742→            fs.inodes.name_to_ino.insert(
743→                (newparent, nfc_key),
744→                source_ino,
745→            );
746→        }
747→
748→        if parent != newparent {
749→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
750→                if let Some(ref mut children) = old_parent.children {
751→                    children.retain(|&c| c != source_ino);
752→                }
753→                old_parent.attr.mtime = SystemTime::now();
754→                old_parent.attr.ctime = SystemTime::now();
755→            }
756→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
757→                if let Some(ref mut children) = new_parent.children {
758→                    children.push(source_ino);
759→                }
760→                new_parent.attr.mtime = SystemTime::now();
761→                new_parent.attr.ctime = SystemTime::now();
762→            }
763→
764→            if let Err(e) = fs.update_folder_metadata(parent) {
765→                log::error!("Failed to update old parent metadata after rename: {}", e);
766→            }
767→            if let Err(e) = fs.update_folder_metadata(newparent) {
768→                log::error!("Failed to update new parent metadata after rename: {}", e);
769→            }
770→        } else {
771→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
772→                parent_inode.attr.mtime = SystemTime::now();
773→                parent_inode.attr.ctime = SystemTime::now();
774→            }
775→            if let Err(e) = fs.update_folder_metadata(parent) {
776→                log::error!("Failed to update parent metadata after rename: {}", e);
777→            }
778→        }
779→
780→        reply.ok();
781→    }
782→}
