120→///
121→/// Shared via `Arc` between `CipherBoxFS` and background publish threads.
122→#[cfg(any(feature = "fuse", feature = "winfsp"))]
123→pub struct PublishCoordinator {
124→    /// Per-IPNS-name sequence number cache (monotonically increasing).
125→    seq_cache: std::sync::Mutex<HashMap<String, u64>>,
126→    /// Per-IPNS-name publish locks to serialize concurrent publishes.
127→    publish_locks: std::sync::Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
128→}
129→
130→#[cfg(any(feature = "fuse", feature = "winfsp"))]
131→impl PublishCoordinator {
132→    pub fn new() -> Self {
133→        Self {
134→            seq_cache: std::sync::Mutex::new(HashMap::new()),
135→            publish_locks: std::sync::Mutex::new(HashMap::new()),
136→        }
137→    }
138→
139→    /// Get or create a per-folder publish lock.
140→    pub fn get_lock(&self, ipns_name: &str) -> Arc<tokio::sync::Mutex<()>> {
141→        let mut locks = self.publish_locks.lock().unwrap();
142→        locks
143→            .entry(ipns_name.to_string())
144→            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
145→            .clone()
146→    }
147→
148→    /// Resolve current sequence number with monotonic cache fallback.
149→    ///
150→    /// - On successful resolve: returns max(resolved, cached)
151→    /// - On failed resolve with cached value: returns cached value with warning
152→    /// - On failed resolve with no cache: returns error (prevents seq rollback)
153→    pub async fn resolve_sequence(
154→        &self,
155→        api: &crate::api::client::ApiClient,
156→        ipns_name: &str,
157→    ) -> Result<u64, String> {
158→        match crate::api::ipns::resolve_ipns(api, ipns_name).await {
159→            Ok(resp) => {
160→                let resolved = match resp.sequence_number.parse::<u64>() {
161→                    Ok(v) => v,
162→                    Err(e) => {
163→                        log::warn!(
164→                            "Failed to parse IPNS sequence '{}' for {}: {}",
165→                            resp.sequence_number, ipns_name, e
166→                        );
167→                        0
168→                    }
169→                };
170→                let cached = self.get_cached(ipns_name).unwrap_or(0);
171→                let seq = std::cmp::max(resolved, cached);
172→                self.update_cache(ipns_name, seq);
173→                Ok(seq)
174→            }
175→            Err(e) => match self.get_cached(ipns_name) {
176→                Some(cached) => {
177→                    log::warn!(
178→                        "IPNS resolve failed for {}, using cached seq {}: {}",
179→                        ipns_name,
180→                        cached,
181→                        e
182→                    );
183→                    Ok(cached)
184→                }
185→                None => Err(format!(
186→                    "IPNS resolve failed and no cached sequence for {}: {}",
187→                    ipns_name, e
188→                )),
189→            },
190→        }
191→    }
192→
193→    /// Record a successful publish — cache is monotonic (only increases).
194→    pub fn record_publish(&self, ipns_name: &str, published_seq: u64) {
195→        self.update_cache(ipns_name, published_seq);
196→    }
197→
198→    fn get_cached(&self, ipns_name: &str) -> Option<u64> {
199→        self.seq_cache.lock().unwrap().get(ipns_name).copied()
200→    }
201→
202→    fn update_cache(&self, ipns_name: &str, seq: u64) {
203→        let mut cache = self.seq_cache.lock().unwrap();
204→        let entry = cache.entry(ipns_name.to_string()).or_insert(0);
205→        if seq > *entry {
206→            *entry = seq;
207→        }
208→    }
209→}
