211→/// Encrypt a FolderMetadata struct and package as JSON bytes ready for IPFS upload.
212→/// CPU-only, no network I/O.
213→#[cfg(any(feature = "fuse", feature = "winfsp"))]
214→fn encrypt_metadata_to_json(
215→    metadata: &crate::crypto::folder::FolderMetadata,
216→    folder_key: &[u8],
217→) -> Result<Vec<u8>, String> {
218→    let folder_key_arr: [u8; 32] = folder_key
219→        .try_into()
220→        .map_err(|_| "Invalid folder key length".to_string())?;
221→    let sealed = crate::crypto::folder::encrypt_folder_metadata(metadata, &folder_key_arr)
222→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
223→    let iv_hex = hex::encode(&sealed[..12]);
224→    use base64::Engine;
225→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
226→    let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
227→    serde_json::to_vec(&json).map_err(|e| format!("JSON serialization failed: {}", e))
228→}
