278→        newSize: number;
279→        forceVersion?: boolean; // true for web re-upload, false/undefined for text editor
280→      }
281→    ): Promise<void> => {
282→      setState({ isLoading: true, error: null });
283→      try {
284→        const folders = useFolderStore.getState().folders;
285→        const vault = useVaultStore.getState();
286→        const auth = useAuthStore.getState();
287→
288→        if (!auth.vaultKeypair) {
289→          throw new Error('No ECIES keypair available - please log in again');
290→        }
291→
292→        // Get parent folder state
293→        const parentFolder =
294→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
295→
296→        if (!parentFolder) {
297→          throw new Error('Parent folder not found or vault not initialized');
298→        }
299→
300→        // 1. Find the FilePointer in parent's children
301→        const filePointer = parentFolder.children.find(
302→          (c) => c.type === 'file' && c.id === fileData.fileId
303→        ) as FilePointer | undefined;
304→
305→        if (!filePointer) {
306→          throw new Error('File not found in folder');
307→        }
308→
309→        // 2. Resolve current file metadata from IPNS
310→        const { metadata: currentMetadata } = await resolveFileMetadata(
311→          filePointer.fileMetaIpnsName,
312→          parentFolder.folderKey
313→        );
314→
315→        // 3. Decrypt the file IPNS private key from FilePointer (or HKDF fallback)
316→        const { privateKey: fileIpnsPrivateKey, migratedIpnsPrivateKeyEncrypted } =
317→          await getFileIpnsPrivateKey(
318→            filePointer,
319→            auth.vaultKeypair.privateKey,
320→            auth.vaultKeypair.publicKey
321→          );
322→
323→        // 4. Determine whether to create a version entry
324→        const createVersion = shouldCreateVersion(currentMetadata, fileData.forceVersion ?? false);
325→
326→        let ipnsRecord: FileIpnsRecordPayload;
327→        let prunedCids: string[];
328→        try {
329→          // 5. Update file metadata and publish new IPNS record
330→          ({ ipnsRecord, prunedCids } = await updateFileMetadata({
331→            fileIpnsPrivateKey,
332→            fileMetaIpnsName: filePointer.fileMetaIpnsName,
333→            folderKey: parentFolder.folderKey,
334→            currentMetadata,
335→            updates: {
336→              cid: fileData.newCid,
337→              fileKeyEncrypted: fileData.newFileKeyEncrypted,
338→              fileIv: fileData.newFileIv,
339→              size: fileData.newSize,
340→            },
341→            createVersion,
342→          }));
343→        } finally {
344→          fileIpnsPrivateKey.fill(0);
345→        }
346→
347→        // 6. Publish only the file IPNS record (folder metadata untouched!)
348→        await folderService.replaceFileInFolder({
349→          fileId: fileData.fileId,
350→          fileIpnsRecord: ipnsRecord,
351→          parentFolderState: parentFolder,
352→        });
353→
354→        // 7. Update local state -- touch modifiedAt and persist migrated IPNS key if applicable
355→        const updatedChildren = parentFolder.children.map((child) => {
356→          if (child.type === 'file' && child.id === fileData.fileId) {
357→            return {
358→              ...child,
359→              modifiedAt: Date.now(),
360→              ...(migratedIpnsPrivateKeyEncrypted
361→                ? { ipnsPrivateKeyEncrypted: migratedIpnsPrivateKeyEncrypted }
362→                : {}),
363→            };
364→          }
365→          return child;
366→        });
367→
368→        const store = useFolderStore.getState();
369→        store.updateFolderChildren(parentId, updatedChildren);
370→
371→        // 7b. Lazy migration: persist wrapped IPNS key to folder metadata on IPFS
372→        if (migratedIpnsPrivateKeyEncrypted) {
373→          folderService
374→            .updateFolderMetadata({
375→              folderId: parentFolder.id,
376→              children: updatedChildren,
377→              folderKey: parentFolder.folderKey,
378→              ipnsPrivateKey: parentFolder.ipnsPrivateKey,
379→              ipnsName: parentFolder.ipnsName,
380→              sequenceNumber: parentFolder.sequenceNumber,
381→            })
382→            .then(({ newSequenceNumber }) => {
383→              useFolderStore.getState().updateFolderSequence(parentId, newSequenceNumber);
384→            })
385→            .catch((err) => {
386→              console.warn('Lazy IPNS key migration: folder re-publish failed, will retry:', err);
387→            });
388→        }
389→
390→        // 8. Only unpin CIDs of pruned versions (excess beyond max 10)
391→        // Old CIDs stay pinned as version history (VER-01)
392→        for (const prunedCid of prunedCids) {
393→          unpinFromIpfs(prunedCid).catch(() => {});
394→        }
395→
396→        // Refresh quota
397→        useQuotaStore.getState().fetchQuota();
398→
399→        setState({ isLoading: false, error: null });
400→      } catch (err) {
401→        const error = err instanceof Error ? err.message : 'Failed to update file';
402→        setState({ isLoading: false, error });
403→        throw err;
404→      }
405→    },
406→    []
407→  );
408→
409→  return {
410→    ...state,
411→    addFile: handleAddFile,
412→    addFiles: handleAddFiles,
413→    updateFile: handleUpdateFile,
414→  };
415→}
