230→/// Spawn a background OS thread to upload encrypted metadata and publish via IPNS.
231→/// Returns immediately — does NOT block the calling thread.
232→#[cfg(any(feature = "fuse", feature = "winfsp"))]
233→fn spawn_metadata_publish(
234→    api: Arc<ApiClient>,
235→    rt: tokio::runtime::Handle,
236→    metadata: crate::crypto::folder::FolderMetadata,
237→    folder_key: Vec<u8>,
238→    ipns_private_key: Vec<u8>,
239→    ipns_name: String,
240→    old_metadata_cid: Option<String>,
241→    coordinator: Arc<PublishCoordinator>,
242→) {
243→    std::thread::spawn(move || {
244→        let result = rt.block_on(async {
245→            // Acquire per-folder publish lock to serialize concurrent publishes
246→            let lock = coordinator.get_lock(&ipns_name);
247→            let _guard = lock.lock().await;
248→
249→            // Encrypt metadata (CPU)
250→            let json_bytes = encrypt_metadata_to_json(&metadata, &folder_key)?;
251→
252→            // Resolve current IPNS sequence number (monotonic cache fallback)
253→            let seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
254→
255→            // Upload encrypted metadata to IPFS
256→            let new_cid = crate::api::ipfs::upload_content(&api, &json_bytes).await?;
257→
258→            // Create and sign IPNS record
259→            let ipns_key_arr: [u8; 32] = ipns_private_key
260→                .try_into()
261→                .map_err(|_| "Invalid IPNS private key length".to_string())?;
262→            let new_seq = seq + 1;
263→            let value = format!("/ipfs/{}", new_cid);
264→            let record = crate::crypto::ipns::create_ipns_record(
265→                &ipns_key_arr,
266→                &value,
267→                new_seq,
268→                86_400_000,
269→            )
270→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
271→            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
272→                .map_err(|e| format!("IPNS record marshal failed: {}", e))?;
273→
274→            use base64::Engine;
275→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
276→
277→            let req = crate::api::ipns::IpnsPublishRequest {
278→                ipns_name: ipns_name.clone(),
279→                record: record_b64,
280→                metadata_cid: new_cid.clone(),
281→                encrypted_ipns_private_key: None,
282→                key_epoch: None,
283→            };
284→            crate::api::ipns::publish_ipns(&api, &req).await?;
285→
286→            // Record successful publish in coordinator cache
287→            coordinator.record_publish(&ipns_name, new_seq);
288→
289→            // Unpin old metadata CID
290→            if let Some(old) = old_metadata_cid {
291→                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
292→            }
293→
294→            log::info!("Background metadata publish succeeded for {}", ipns_name);
295→            Ok::<(), String>(())
296→        });
297→
298→        if let Err(e) = result {
299→            log::error!("Background metadata publish failed: {}", e);
300→        }
301→    });
302→}
