 1→//! Status state machine for the system tray icon.
 2→//!
 3→//! Represents all possible states of the desktop app as displayed
 4→//! in the menu bar tray icon's status line.
 5→
 6→/// All possible states the desktop app can be in.
 7→///
 8→/// The tray menu status line displays the human-readable label
 9→/// returned by `TrayStatus::label()`.
10→#[derive(Debug, Clone, PartialEq)]
11→pub enum TrayStatus {
12→    /// No auth, no mount -- initial state and post-logout state.
13→    NotConnected,
14→    /// Auth complete, FUSE filesystem is mounting.
15→    Mounting,
16→    /// Background sync is actively polling/refreshing metadata.
17→    Syncing,
18→    /// Up to date -- last sync completed successfully.
19→    Synced,
20→    /// Network unavailable -- waiting for connectivity to resume.
21→    Offline,
22→    /// Something went wrong (with human-readable description).
23→    Error(String),
24→}
25→
26→impl TrayStatus {
27→    /// Human-readable status text for the tray menu item.
28→    pub fn label(&self) -> &str {
29→        match self {
30→            TrayStatus::NotConnected => "Not Connected",
31→            TrayStatus::Mounting => "Mounting...",
32→            TrayStatus::Syncing => "Syncing...",
33→            TrayStatus::Synced => "Synced",
34→            TrayStatus::Offline => "Offline",
35→            TrayStatus::Error(_) => "Error",
36→        }
37→    }
38→
39→    /// Returns `true` when the app is authenticated and has (or had) a mounted filesystem.
40→    ///
41→    /// True for Syncing, Synced, Offline (connected but temporarily unreachable).
42→    /// False for NotConnected, Mounting, Error.
43→    pub fn is_connected(&self) -> bool {
44→        matches!(self, TrayStatus::Syncing | TrayStatus::Synced | TrayStatus::Offline)
45→    }
46→}
47→
48→#[cfg(test)]
49→mod tests {
50→    use super::*;
51→
52→    #[test]
53→    fn test_labels() {
54→        assert_eq!(TrayStatus::NotConnected.label(), "Not Connected");
55→        assert_eq!(TrayStatus::Mounting.label(), "Mounting...");
56→        assert_eq!(TrayStatus::Syncing.label(), "Syncing...");
57→        assert_eq!(TrayStatus::Synced.label(), "Synced");
58→        assert_eq!(TrayStatus::Offline.label(), "Offline");
59→        assert_eq!(TrayStatus::Error("disk full".into()).label(), "Error");
60→    }
61→
62→    #[test]
63→    fn test_is_connected() {
64→        assert!(!TrayStatus::NotConnected.is_connected());
65→        assert!(!TrayStatus::Mounting.is_connected());
66→        assert!(TrayStatus::Syncing.is_connected());
67→        assert!(TrayStatus::Synced.is_connected());
68→        assert!(TrayStatus::Offline.is_connected());
69→        assert!(!TrayStatus::Error("oops".into()).is_connected());
70→    }
